import { useState, useEffect } from "react";
import { useMutation, useQueryClient, useQuery } from "@tanstack/react-query";
import { base44, apiFetch, api } from "../api/base44Client";
import { INITIAL_ATR_MULTIPLIER, ATR_PERIOD_DAYS } from "../constants/strategy";
import { useNavigate, useLocation } from "react-router-dom";
import { createPageUrl } from "../utils";
import { motion } from "framer-motion";
import { toast } from "sonner";
import { Button } from "../components/ui/button";
import { Input } from "../components/ui/input";
import { Label } from "../components/ui/label";
import { Textarea } from "../components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "../components/ui/select";
import PageHeader from "../components/ui/PageHeader";
import { PAGE_LABELS } from "../lib/pageLabels";
import { ArrowLeft, Calculator, Loader2, CheckCircle2, X, Rocket, Info } from "lucide-react";
import { Link } from "react-router-dom";
import { cn } from "../lib/utils";
import { formatCurrency, currencyForMarket } from "../lib/format";
import PositionSizingWidget from '../components/trades/PositionSizingWidget';
import { INPUT_DEBOUNCE_MS } from "../hooks/usePositionSizingFetch";
import { format } from "date-fns";
import SetupThesisDigestPanel from '../components/trades/SetupThesisDigestPanel';
import PreEntryValidationPanel from '../components/trades/PreEntryValidationPanel';
import { isStartTradeEligible, STATUS_CONFIG } from "./TradePlans";
import { FX_SOURCE_LAST_KNOWN, FX_SOURCE_CONSTANT, formatFxAge, formatFxRate } from "../lib/fxSource";
import { todayLocal } from "../lib/localDate";

const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:8000";

export default function TradeEntry() {
  const navigate = useNavigate();
  const location = useLocation();
  const queryClient = useQueryClient();

  // Pre-populate from watchlist "Add to Position" if state was passed
  const prefill = location.state?.watchlist_prefill || null;
  // ST-01 (EPIC-01, v7.3): pre-population + trade_plan_id link from "Start Trade from Plan"
  const planPrefill = location.state?.trade_plan_prefill || null;
  const prefillMarket = planPrefill?.market || prefill?.market || "UK";

  const [formData, setFormData] = useState({
    ticker: (planPrefill?.ticker || prefill?.ticker || "").trim().toUpperCase(),
    market: prefillMarket,
    entry_date: todayLocal(),
    shares: planPrefill?.quantity != null ? String(planPrefill.quantity) : "",
    entry_price: planPrefill?.entry_price != null ? String(planPrefill.entry_price) : (prefill?.entry_price || ""),
    fill_price: "",
    // ST-02 (BLG-FE-245, v9.15): US starts empty and is pre-filled from the
    // live rate below; no client-side constant is pre-filled.
    fx_rate: prefillMarket === "US" ? "" : "1",
    atr_value: "",
    entry_note: "",
    tags: [],
  });

  // ST-02 (BLG-FE-245, EPIC-01, v9.15): pre-fill the US FX rate from
  // GET /market/status (position_form.md v1.12 §FX Rate). A value the user
  // has typed is never overwritten.
  const [fxTyped, setFxTyped] = useState(false);
  const [fxSubmitAttempted, setFxSubmitAttempted] = useState(false);
  const { data: marketStatus, isLoading: fxLoading, isError: fxError } = useQuery({
    queryKey: ["marketStatus"],
    queryFn: async () => {
      const response = await apiFetch(`${API_BASE_URL}/market/status`);
      if (!response.ok) throw new Error(`market/status ${response.status}`);
      const result = await response.json();
      return result.data;
    },
    enabled: formData.market === "US",
    retry: false,
  });
  const liveFxRate = typeof marketStatus?.fx_rate === "number" && marketStatus.fx_rate > 0 ? marketStatus.fx_rate : null;

  useEffect(() => {
    if (formData.market !== "US" || fxTyped || liveFxRate == null) return;
    const filled = formatFxRate(liveFxRate);
    setFormData((prev) => (prev.market === "US" && prev.fx_rate !== filled ? { ...prev, fx_rate: filled } : prev));
  }, [formData.market, fxTyped, liveFxRate]);

  // AC-03: manually-entered trades (no plan origin) can still optionally link
  // an existing, not-yet-started trade plan. Locked to planPrefill.id when
  // arriving via "Start Trade from Plan" — that link is automatic (AC-02).
  const [linkedPlanId, setLinkedPlanId] = useState(planPrefill?.id || null);

  // ST-02 (v8.6, EPIC-01, BLG-FEAT-56): fetch the full linked plan record
  // (setup_thesis, early_exit_conditions, confirmation_criteria) for the
  // Setup Thesis Digest panel (trade_plan.md §10.5). Covers both the
  // automatic hand-off (§10.2) and the manual link selector (§10.3) — both
  // paths converge on linkedPlanId. No new AI call — reads already-generated
  // plan content.
  const { data: linkedPlan } = useQuery({
    queryKey: ["trade-plan", linkedPlanId],
    queryFn: () => api.tradePlans.getById(linkedPlanId),
    enabled: !!linkedPlanId,
    retry: false,
  });

  const { data: linkablePlans = [] } = useQuery({
    queryKey: ["trade-plans-linkable"],
    queryFn: async () => {
      const res = await apiFetch(`${API_BASE_URL}/trade-plans`);
      const json = await res.json();
      return (json.data || []).filter(isStartTradeEligible);
    },
    enabled: !planPrefill,
  });

  // ST-17 (BLG-BE-146, v9.12): ATR preview — position_form.md v1.9 §ATR (14-day).
  // Once the ticker is known and the ATR field is blank, fetch the 14-day ATR
  // (GET /market/atr/{ticker}) after the same 300 ms input debounce, so the
  // stop, risk and sizing show before save. The fetched value is never placed
  // into the input: the field is submitted blank, so the backend still fetches
  // the ATR itself at save. A typed ATR always takes precedence.
  // status: idle | loading | ready | none
  const [atrPreview, setAtrPreview] = useState({ status: "idle" });
  // ST-05 (BLG-FE-222, v9.15): one normalised ticker (trim, upper-case) for
  // the ATR preview, the pre-entry checks and the submit.
  const normalizedTicker = formData.ticker.trim().toUpperCase();
  const previewTicker = normalizedTicker;
  const atrBlank = String(formData.atr_value).trim() === "";

  useEffect(() => {
    if (!previewTicker || !atrBlank) {
      setAtrPreview({ status: "idle" });
      return undefined;
    }
    let cancelled = false;
    setAtrPreview({ status: "loading" });
    const timer = setTimeout(async () => {
      try {
        const res = await api.market.getAtr(previewTicker, formData.market);
        if (cancelled) return;
        const atr = typeof res?.atr === "number" && res.atr > 0 ? res.atr : null;
        setAtrPreview(atr != null ? { status: "ready", atr, asOf: res.as_of } : { status: "none" });
      } catch {
        // No error banner: a failed fetch falls back to "Calculated on save".
        if (!cancelled) setAtrPreview({ status: "none" });
      }
    }, INPUT_DEBOUNCE_MS);
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [previewTicker, formData.market, atrBlank]);

  // ST-18 (BLG-FE-203, v9.12): a typed ATR where 5× ATR ≥ entry puts the stop
  // at or below zero (usually an ATR typed in pence or cents). The inline error
  // shows on blur or a submit attempt and disables submit while shown
  // (position_form.md v1.9 §ATR (14-day), §Validation Errors).
  const [atrTouched, setAtrTouched] = useState(false);
  const atrImplausible =
    parseFloat(formData.atr_value) > 0 &&
    parseFloat(formData.entry_price) > 0 &&
    INITIAL_ATR_MULTIPLIER * parseFloat(formData.atr_value) >= parseFloat(formData.entry_price);
  const showAtrError = atrTouched && atrImplausible;
  const marketKnown = previewTicker !== "";

  // ST-01 (BLG-FE-244, EPIC-01, v9.15): the §4.2 pre-entry checks on every
  // route into Trade Entry (position_form.md v1.13 §Pre-Entry Checks). Hidden
  // only when a linked plan already ran them (stored snapshot), so the panel
  // shows at most once. Branch A (ESC-EXEC-20261104-01, strategy_rules.md
  // §4.2.6 v1.23): an unacknowledged WARN/FAIL disables Submit.
  const [preEntryAck, setPreEntryAck] = useState(false);
  const [preEntryNeedsAck, setPreEntryNeedsAck] = useState(false);
  const planRanChecks = !!linkedPlanId && linkedPlan?.pre_entry_validation_snapshot != null;
  const showPreEntryChecks = !planRanChecks;
  const preEntryAckRequired = showPreEntryChecks && preEntryNeedsAck && !preEntryAck;

  const [tagInput, setTagInput] = useState("");
  const [showTagSuggestions, setShowTagSuggestions] = useState(false);

  const { data: settings } = useQuery({
    queryKey: ["settings"],
    queryFn: () => base44.entities.Settings.list(),
  });

  const { data: existingTags = [] } = useQuery({
    queryKey: ["position-tags"],
    queryFn: async () => {
      const positions = await base44.entities.Position.list();
      const allTags = positions.flatMap(p => p.tags || []);
      return [...new Set(allTags)].sort();
    },
  });

  const currentSettings = settings?.[0] || {
    uk_commission: 9.95,
    us_commission: 0,
    stamp_duty_rate: 0.005,
    fx_fee_rate: 0.0015,
  };

  // Read default_risk_percent from settings for PositionSizingWidget
  const defaultRiskPercent = settings?.[0]?.default_risk_percent ?? 1.0;

  const createMutation = useMutation({
    mutationFn: (data) => base44.entities.Position.create(data),
    onSuccess: (response) => {
      queryClient.invalidateQueries({ queryKey: ["positions"] });
      // Bug fix (user-reported, live): adding a position deducts cash
      // (position_service.py's add_position() debits portfolio.cash) but this
      // handler never invalidated any portfolio/cash query, so the cash balance
      // shown everywhere (the global "Manage Cash" trigger, this page's own
      // PositionSizingWidget available-cash figure, etc.) stayed stale until a
      // full page reload remounted everything fresh. "portfolioApi" is the key
      // Layout.js's global trigger and Dashboard.js both use; "portfolio" is
      // invalidated too for parity with Positions.js's exitMutation (the same
      // class of bug, same fix, found and applied there in this pass as well).
      queryClient.invalidateQueries({ queryKey: ["portfolioApi"] });
      queryClient.invalidateQueries({ queryKey: ["portfolio"] });
      // ST-07 (BLG-FE-197, v9.10): confirm the stop the backend actually stored.
      const storedStop = response?.initial_stop != null
        ? ` Initial stop ${formatCurrency(response.initial_stop, { currency: currencyForMarket(formData.market) })}.`
        : "";
      if (response?.trade_plan_linked) {
        toast.success(`Linked to trade plan for ${response.ticker}.${storedStop}`);
      } else {
        toast.info(`No matching plan found — logged unlinked.${storedStop}`);
      }
      // If opened from watchlist, delete the watchlist entry then go to Positions
      if (prefill?.id) {
        fetch(`${API_BASE_URL}/watchlist/${prefill.id}`, { method: "DELETE" })
          .catch(() => {}) // non-blocking — position was created successfully
          .finally(() => navigate(createPageUrl("Positions")));
      } else {
        navigate(createPageUrl("Positions"));
      }
    },
    // Bug fix (this session, P1): this mutation had no onError handler at all — a
    // 400 from POST /portfolio/position (e.g. "Insufficient funds...") failed
    // completely silently: no toast, no message, the button just re-enabled with
    // no explanation. See also the doFetch fix in base44Client.js, which was
    // dropping the backend's actual error text in favour of a generic message.
    onError: (error) => {
      toast.error(error?.message || "Failed to add position.");
    },
  });

  const handleChange = (field, value) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  const detectMarket = (ticker) => {
    if (ticker.endsWith(".L") || /^[A-Z]{2,4}$/.test(ticker)) {
      return "UK";
    }
    return "US";
  };

  // Switching market resets FX: UK uses 1; US waits for the live pre-fill
  // (ST-02) unless the user has typed a US rate.
  const withMarket = (prev, market) => {
    if (market === prev.market) return prev;
    if (market === "US") return { ...prev, market, fx_rate: "" };
    return { ...prev, market, fx_rate: "1" };
  };

  const handleMarketChange = (market) => {
    if (market !== formData.market) setFxTyped(false);
    setFormData((prev) => withMarket(prev, market));
  };

  const handleTickerChange = (value) => {
    const market = detectMarket(value.toUpperCase());
    if (market !== formData.market) setFxTyped(false);
    setFormData((prev) => ({ ...withMarket(prev, market), ticker: value.toUpperCase() }));
  };

  const handleFxChange = (value) => {
    setFxTyped(true);
    handleChange("fx_rate", value);
  };

  // ST-02: the line under the FX field naming where the value came from.
  const fxSourceLine = (() => {
    if (formData.market !== "US") return null;
    const source = marketStatus?.fx_rate_source;
    if (fxTyped) {
      const live = liveFxRate != null && source !== FX_SOURCE_CONSTANT ? `live rate ${formatFxRate(liveFxRate)}` : "no live rate";
      return { text: `Entered by you (${live})`, warn: false };
    }
    if (fxLoading) return null;
    if (fxError || liveFxRate == null) return { text: "No rate available: enter the rate", warn: true };
    const asOf = marketStatus?.fx_rate_as_of;
    if (source === FX_SOURCE_CONSTANT) return { text: "Fallback rate: no live rate is available", warn: true };
    if (source === FX_SOURCE_LAST_KNOWN) return { text: asOf ? `Not live: last rate from ${formatFxAge(asOf)}` : "Not live: last rate", warn: true };
    return { text: asOf ? `Live rate, ${formatFxAge(asOf)}` : "Live rate", warn: false };
  })();

  const defaultTags = ["momentum", "breakout", "pullback", "news-driven", "high-conviction"];
  const allAvailableTags = [...new Set([...existingTags, ...defaultTags])];

  const filteredTags = tagInput
    ? allAvailableTags.filter(tag =>
        tag.toLowerCase().includes(tagInput.toLowerCase()) &&
        !formData.tags.includes(tag)
      )
    : allAvailableTags.filter(tag => !formData.tags.includes(tag));

  const handleAddTag = (tag) => {
    if (formData.tags.length >= 5) return;
    const normalizedTag = tag.toLowerCase().replace(/\s+/g, "-");
    if (!formData.tags.includes(normalizedTag)) {
      setFormData(prev => ({ ...prev, tags: [...prev.tags, normalizedTag] }));
    }
    setTagInput("");
    setShowTagSuggestions(false);
  };

  const handleRemoveTag = (tagToRemove) => {
    setFormData(prev => ({
      ...prev,
      tags: prev.tags.filter(tag => tag !== tagToRemove)
    }));
  };

  const handleTagInputKeyDown = (e) => {
    if (e.key === "Enter" && tagInput.trim()) {
      e.preventDefault();
      handleAddTag(tagInput.trim());
    }
  };

  // ─────────────────────────────────────────────────────────────────────────────
  // Cost preview — client-side estimate for display only.
  // These values are NOT passed to the backend on submission.
  // Authoritative fee and stop calculations are performed server-side by
  // POST /portfolio/position per strategy_rules.md §4.1.
  // ─────────────────────────────────────────────────────────────────────────────
  const estimateCosts = () => {
    const shares = parseFloat(formData.shares) || 0;
    const price = parseFloat(formData.entry_price) || 0;
    const fxRate = parseFloat(formData.fx_rate) || 1;
    const typedAtr = parseFloat(formData.atr_value) || 0;
    // ST-17: with the field blank, the previewed ATR drives the stop.
    const stopFromPreview = atrBlank && atrPreview.status === "ready";
    const atr = stopFromPreview ? atrPreview.atr : typedAtr;

    const grossValue = shares * price;
    const grossValueGBP = formData.market === "US" ? grossValue / fxRate : grossValue;

    const commission = formData.market === "UK"
      ? currentSettings.uk_commission
      : currentSettings.us_commission;

    const stampDuty = formData.market === "UK"
      ? grossValueGBP * currentSettings.stamp_duty_rate
      : 0;

    const fxFee = formData.market === "US"
      ? grossValueGBP * (currentSettings.fx_fee_rate || 0.0015)
      : 0;

    const totalCost = grossValueGBP + commission + stampDuty + fxFee;

    // ST-07 (BLG-FE-197, v9.10): the stop add_position() will store —
    // entry − 5× ATR (§5), multiplier from the fixed §11 source (ST-01). The
    // backend ignores any submitted stop, so no input may set it. Unknown
    // (null) until both entry price and ATR are present; the backend fetches
    // ATR on save when the field is blank.
    const rawStop = price > 0 && atr > 0 ? price - (atr * INITIAL_ATR_MULTIPLIER) : null;
    // ST-06 (EPIC-02, v9.13, BLG-BE-180): a stop at or below zero is never shown.
    // With the fetched ATR, §5 gives no stop for this entry (Strategy Rules &
    // System Intent Owner ruling (A)): "No valid stop" and Submit disabled. With a
    // typed ATR, the existing implausible-ATR error explains it, so the value is "—".
    const stopAtOrBelowZero = rawStop != null && rawStop <= 0;
    const stopInvalid = stopAtOrBelowZero && stopFromPreview;
    const systemStop = stopAtOrBelowZero ? null : rawStop;

    // Risk is computed from the system stop only.
    const riskPerShare = systemStop != null ? price - systemStop : null;
    const totalRisk = riskPerShare != null ? riskPerShare * shares : null;
    const totalRiskGBP = totalRisk == null ? null : (formData.market === "US" ? totalRisk / fxRate : totalRisk);

    return {
      grossValue,
      grossValueGBP,
      commission,
      stampDuty,
      fxFee,
      totalCost,
      systemStop,
      stopFromPreview,
      stopInvalid,
      stopAtOrBelowZero,
      previewAtr: stopFromPreview ? atr : null,
      riskPerShare,
      totalRisk: totalRiskGBP,
      currencySymbol: formData.market === "UK" ? "£" : "$",
    };
  };

  const costs = estimateCosts();
  const isFormValid = formData.ticker && formData.shares && formData.entry_price;
  // ST-02 (position_form.md §FX Rate, §Validation Errors): a US entry needs an
  // FX rate. With no live rate the field stays empty and save is refused with
  // an inline error, so no unseen server-side rate is stored.
  const fxMissing = formData.market === "US" && !(parseFloat(formData.fx_rate) > 0);
  const showFxMissing = fxSubmitAttempted && fxMissing;

  const handleSubmit = () => {
    if (!isFormValid || preEntryAckRequired) return;
    if (fxMissing) {
      setFxSubmitAttempted(true);
      return;
    }
    if (atrImplausible) {
      setAtrTouched(true);
      return;
    }

    // Note: fees are NOT passed here — the backend calculates authoritative fees
    // via POST /portfolio/position. No stop is sent: the backend sets the
    // initial stop from entry and ATR (ST-07, BLG-FE-197).
    createMutation.mutate({
      ticker: normalizedTicker,
      market: formData.market,
      entry_date: formData.entry_date,
      shares: parseFloat(formData.shares),
      entry_price: parseFloat(formData.entry_price),
      fill_price: formData.fill_price ? parseFloat(formData.fill_price) : undefined,
      current_price: parseFloat(formData.entry_price),
      fx_rate: parseFloat(formData.fx_rate),
      atr_value: parseFloat(formData.atr_value) || null,
      status: "open",
      entry_note: formData.entry_note || null,
      tags: formData.tags.length > 0 ? formData.tags : null,
      trade_plan_id: linkedPlanId || null,
      pre_entry_override_acknowledged: showPreEntryChecks && preEntryNeedsAck && preEntryAck ? true : undefined,
    });
  };

  return (
    <div className="space-y-6 max-w-2xl mx-auto">
      <PageHeader
        title={PAGE_LABELS.TradeEntry}
        description="Add a new trade to your portfolio"
        actions={
          <Link to={createPageUrl("Positions")}>
            <Button variant="ghost" className="text-slate-600 dark:text-slate-400 hover:text-white hover:bg-slate-800">
              <ArrowLeft className="w-4 h-4 mr-2" />
              Back
            </Button>
          </Link>
        }
      />

      {planPrefill && (
        <div
          data-testid="trade-plan-linked-banner"
          className="rounded-xl bg-emerald-500/10 border border-emerald-500/30 px-4 py-3 text-sm text-emerald-300 flex items-center gap-2"
        >
          <Rocket className="w-4 h-4 shrink-0" />
          Linked to trade plan for {planPrefill.ticker} — saving this trade will mark that plan Active.
        </div>
      )}

      {/* ST-02 (v8.6, EPIC-01, BLG-FEAT-56): Setup Thesis Digest — trade_plan.md §10.5.
          Renders below the "Linked to trade plan" indicator, above the order form fields. */}
      {linkedPlan && <SetupThesisDigestPanel plan={linkedPlan} />}

      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="rounded-2xl bg-gradient-to-br from-slate-900 to-slate-800 border border-slate-700/50 p-6"
      >
        <div className="space-y-6">
          {!planPrefill && linkablePlans.length > 0 && (
            <div className="space-y-2">
              <Label className="text-slate-600 dark:text-slate-400">Link to Trade Plan (optional)</Label>
              <Select
                value={linkedPlanId || "none"}
                onValueChange={(value) => setLinkedPlanId(value === "none" ? null : value)}
              >
                <SelectTrigger data-testid="link-trade-plan-select" className="bg-slate-800/50 border-slate-700 text-white">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="bg-slate-800 border-slate-700">
                  <SelectItem value="none">No plan — manual entry</SelectItem>
                  {linkablePlans.map((plan) => (
                    <SelectItem key={plan.id} value={plan.id}>
                      {plan.ticker} ({plan.market || "US"}) — {STATUS_CONFIG[plan.status]?.label || plan.status}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* Ticker & Market */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label className="text-slate-600 dark:text-slate-400">Ticker Symbol</Label>
              <Input
                value={formData.ticker}
                onChange={(e) => handleTickerChange(e.target.value)}
                placeholder="e.g., AAPL or VOD.L"
                className="bg-slate-800/50 border-slate-700 text-white placeholder:text-slate-600 dark:text-slate-400 focus:border-cyan-500/50 focus:ring-cyan-500/20"
              />
            </div>
            <div className="space-y-2">
              <Label className="text-slate-600 dark:text-slate-400">Market</Label>
              <Select
                value={formData.market}
                onValueChange={handleMarketChange}
              >
                <SelectTrigger className="bg-slate-800/50 border-slate-700 text-white">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="bg-slate-800 border-slate-700">
                  <SelectItem value="UK">UK</SelectItem>
                  <SelectItem value="US">US</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* Entry Date */}
          <div className="space-y-2">
            <Label className="text-slate-600 dark:text-slate-400">Entry Date</Label>
            <Input
              type="date"
              value={formData.entry_date}
              onChange={(e) => handleChange("entry_date", e.target.value)}
              className="bg-slate-800/50 border-slate-700 text-white"
            />
          </div>

          {/* Entry Price */}
          <div className="space-y-2">
            <Label className="text-slate-600 dark:text-slate-400">Fill Price ({costs.currencySymbol})</Label>
            <Input
              type="number"
              step="0.01"
              value={formData.entry_price}
              onChange={(e) => handleChange("entry_price", e.target.value)}
              placeholder="0.00"
              className="bg-slate-800/50 border-slate-700 text-white placeholder:text-slate-600 dark:text-slate-400"
            />
          </div>

          {/* Fill Price (optional) */}
          <div className="space-y-2">
            <Label className="text-slate-600 dark:text-slate-400">Fill Price (optional)</Label>
            <Input
              type="number"
              step="0.01"
              value={formData.fill_price}
              onChange={(e) => handleChange("fill_price", e.target.value)}
              placeholder="Actual broker fill price"
              className="bg-slate-800/50 border-slate-700 text-white placeholder:text-slate-600 dark:text-slate-400"
            />
          </div>

          {/* FX Rate (US only) */}
          {formData.market === "US" && (
            <div className="space-y-2">
              {/* ST-03 (BLG-FE-246, v9.15): one FX label and hint on every FX input */}
              <Label htmlFor="trade-entry-fx-rate" className="text-slate-600 dark:text-slate-400">FX rate — USD per £1 (GBP/USD)</Label>
              <Input
                type="number"
                step="0.0001"
                value={formData.fx_rate}
                onChange={(e) => handleFxChange(e.target.value)}
                placeholder={fxLoading && !fxTyped ? "Fetching live rate…" : undefined}
                id="trade-entry-fx-rate"
                aria-invalid={showFxMissing ? "true" : undefined}
                aria-describedby={["trade-entry-fx-hint", fxSourceLine && "trade-entry-fx-source", showFxMissing && "trade-entry-fx-missing"].filter(Boolean).join(" ")}
                data-testid="trade-entry-fx-input"
                className="bg-slate-800/50 border-slate-700 text-white"
              />
              <p id="trade-entry-fx-hint" data-testid="fx-rate-hint" className="text-xs text-slate-600 dark:text-slate-400">How many US dollars £1 buys.</p>
              {fxSourceLine && (
                <p
                  id="trade-entry-fx-source"
                  data-testid="trade-entry-fx-source"
                  className={fxSourceLine.warn ? "text-xs text-amber-700 dark:text-amber-400" : "text-xs text-slate-600 dark:text-slate-400"}
                >
                  {fxSourceLine.text}
                </p>
              )}
              {showFxMissing && (
                <p id="trade-entry-fx-missing" data-testid="trade-entry-fx-missing" className="text-xs text-rose-700 dark:text-rose-400">
                  FX rate missing for US trades. Enter the rate to save.
                </p>
              )}
            </div>
          )}

          {/* ATR & system initial stop (ST-07, BLG-FE-197, v9.10 — position_form.md §ATR (14-day), §Initial Stop) */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="trade-entry-atr" className="text-slate-600 dark:text-slate-400">
                {marketKnown ? `ATR (${ATR_PERIOD_DAYS}-day, ${costs.currencySymbol})` : `ATR (${ATR_PERIOD_DAYS}-day)`}
              </Label>
              <Input
                id="trade-entry-atr"
                type="number"
                step="0.01"
                value={formData.atr_value}
                onChange={(e) => handleChange("atr_value", e.target.value)}
                onBlur={() => setAtrTouched(true)}
                aria-invalid={showAtrError ? "true" : undefined}
                aria-describedby={showAtrError ? "atr-implausible-error" : undefined}
                placeholder="Fetched automatically if blank"
                className="bg-slate-800/50 border-slate-700 text-white placeholder:text-slate-600 dark:text-slate-400"
              />
              {showAtrError && (
                <p id="atr-implausible-error" data-testid="atr-implausible-error" className="text-xs text-rose-700 dark:text-rose-400">
                  This ATR puts the stop at or below zero. Check the unit: ATR is in {costs.currencySymbol}, not pence or cents.
                </p>
              )}
              {atrBlank && atrPreview.status === "ready" && (
                <p data-testid="atr-fetched-hint" className="text-xs text-slate-600 dark:text-slate-400">
                  Fetched: {formatCurrency(atrPreview.atr, { currency: currencyForMarket(formData.market) })} ({ATR_PERIOD_DAYS}-day
                  {atrPreview.asOf && !Number.isNaN(new Date(atrPreview.asOf).getTime())
                    ? `, ${format(new Date(atrPreview.asOf), "d MMM")}`
                    : ""})
                </p>
              )}
            </div>
            <div className="space-y-2" data-testid="system-initial-stop">
              <p className="text-sm font-medium text-slate-600 dark:text-slate-400">Initial Stop (set by system)</p>
              {costs.stopInvalid ? (
                <>
                  <p className="text-sm font-semibold text-rose-700 dark:text-rose-400" data-testid="system-initial-stop-value">No valid stop</p>
                  <p data-testid="initial-stop-invalid" role="status" className="text-xs text-rose-700 dark:text-rose-400">
                    {INITIAL_ATR_MULTIPLIER}× the fetched {ATR_PERIOD_DAYS}-day ATR ({formatCurrency(costs.previewAtr, { currency: currencyForMarket(formData.market) })}) is at or above the entry price, so the stop would be at or below zero. §5 cannot set a stop for this entry.
                  </p>
                </>
              ) : costs.stopAtOrBelowZero ? (
                <p className="text-sm font-semibold text-slate-300" data-testid="system-initial-stop-value">—</p>
              ) : costs.systemStop != null ? (
                <>
                  <p className="text-sm font-semibold text-rose-400" data-testid="system-initial-stop-value">
                    {formatCurrency(costs.systemStop, { currency: currencyForMarket(formData.market) })}
                  </p>
                  <p className="text-xs text-slate-600 dark:text-slate-400">
                    {costs.stopFromPreview
                      ? `Entry − ${INITIAL_ATR_MULTIPLIER}× ATR (§5), using the fetched ${ATR_PERIOD_DAYS}-day ATR. The stop is recalculated at save and may differ slightly if prices update before then.`
                      : `Entry − ${INITIAL_ATR_MULTIPLIER}× ATR (§5). This is the stop that will be stored.`}
                  </p>
                </>
              ) : parseFloat(formData.entry_price) > 0 && atrBlank && atrPreview.status === "loading" ? (
                <p className="text-sm font-semibold text-slate-600 dark:text-slate-400" data-testid="system-initial-stop-value">Fetching ATR…</p>
              ) : parseFloat(formData.entry_price) > 0 ? (
                <>
                  <p className="text-sm font-semibold text-slate-300" data-testid="system-initial-stop-value">Calculated on save</p>
                  <p className="text-xs text-slate-600 dark:text-slate-400">
                    The system fetches the {ATR_PERIOD_DAYS}-day ATR for {formData.ticker || "this ticker"} and sets the stop at Entry − {INITIAL_ATR_MULTIPLIER}× ATR.
                  </p>
                </>
              ) : (
                <p className="text-sm font-semibold text-slate-300" data-testid="system-initial-stop-value">—</p>
              )}
              {planPrefill?.stop_price != null && (
                <p className="text-xs text-slate-600 dark:text-slate-400" data-testid="plan-stop-reference">
                  Trade plan stop: {formatCurrency(planPrefill.stop_price, { currency: currencyForMarket(formData.market) })}. Shown for reference; the stored stop follows the strategy formula.
                </p>
              )}
            </div>
          </div>

          {/* Position Sizing Widget — calls POST /portfolio/size, backend-authoritative */}
          {/* DEF-002 / DEF-003 fix: pass null only when field is empty string, not when value is 0 */}
          <PositionSizingWidget
            entryPrice={formData.entry_price === "" ? null : parseFloat(formData.entry_price)}
            stopPrice={costs.systemStop}
            market={formData.market}
            fxRate={parseFloat(formData.fx_rate) || null}
            shares={formData.shares}
            onSharesChange={(val) => handleChange("shares", val)}
            defaultRiskPercent={defaultRiskPercent}
            ticker={formData.ticker || null}
          />

          {/* Shares */}
          <div className="space-y-2">
            <Label className="text-slate-600 dark:text-slate-400">Number of Shares</Label>
            <Input
              type="number"
              value={formData.shares}
              onChange={(e) => handleChange("shares", e.target.value)}
              placeholder="0"
              className="bg-slate-800/50 border-slate-700 text-white placeholder:text-slate-600 dark:text-slate-400"
            />
          </div>

          {/* Entry Note */}
          <div className="space-y-2">
            <Label className="text-slate-600 dark:text-slate-400">Entry Note (Optional)</Label>
            <Textarea
              value={formData.entry_note}
              onChange={(e) => {
                if (e.target.value.length <= 500) {
                  handleChange("entry_note", e.target.value);
                }
              }}
              placeholder="Why are you entering this trade? What's your thesis?"
              className="bg-slate-800/50 border-slate-700 text-white placeholder:text-slate-600 dark:text-slate-400 focus:border-cyan-500/50 focus:ring-cyan-500/20 resize-none"
              rows={4}
            />
            <div className="flex justify-end">
              <span className={cn(
                "text-xs",
                formData.entry_note.length > 450 ? "text-rose-400" : "text-slate-600 dark:text-slate-400"
              )}>
                {formData.entry_note.length}/500
              </span>
            </div>
          </div>

          {/* Tags */}
          <div className="space-y-2">
            <Label className="text-slate-600 dark:text-slate-400">Tags (Optional)</Label>
            <div className="space-y-2">
              {formData.tags.length > 0 && (
                <div className="flex flex-wrap gap-2">
                  {formData.tags.map((tag) => (
                    <span
                      key={tag}
                      className="inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-medium bg-cyan-500/20 text-cyan-400 border border-cyan-500/30"
                    >
                      {tag}
                      <button
                        onClick={() => handleRemoveTag(tag)}
                        className="hover:text-cyan-300 transition-colors"
                      >
                        <X className="w-3 h-3" />
                      </button>
                    </span>
                  ))}
                </div>
              )}

              {formData.tags.length < 5 && (
                <div className="relative">
                  <Input
                    value={tagInput}
                    onChange={(e) => {
                      setTagInput(e.target.value);
                      setShowTagSuggestions(e.target.value.length > 0);
                    }}
                    onFocus={() => setShowTagSuggestions(true)}
                    onBlur={() => setTimeout(() => setShowTagSuggestions(false), 200)}
                    onKeyDown={handleTagInputKeyDown}
                    placeholder="Type to add tags..."
                    className="bg-slate-800/50 border-slate-700 text-white placeholder:text-slate-600 dark:text-slate-400 focus:border-cyan-500/50 focus:ring-cyan-500/20"
                  />
                  {showTagSuggestions && filteredTags.length > 0 && (
                    <div className="absolute z-10 w-full mt-1 bg-slate-800 border border-slate-700 rounded-lg shadow-xl max-h-48 overflow-auto">
                      {filteredTags.slice(0, 10).map((tag) => (
                        <button
                          key={tag}
                          onClick={() => handleAddTag(tag)}
                          className="w-full px-3 py-2 text-left text-sm text-slate-300 hover:bg-slate-700 hover:text-white transition-colors"
                        >
                          {tag}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              )}

              {formData.tags.length >= 5 && (
                <p className="text-xs text-slate-600 dark:text-slate-400">Maximum 5 tags reached</p>
              )}
            </div>
          </div>
        </div>
      </motion.div>

      {/* Cost Preview — client-side estimate only. Actual fees calculated server-side. */}
      {isFormValid && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="rounded-2xl bg-gradient-to-br from-slate-900 to-slate-800 border border-slate-700/50 p-6"
        >
          <div className="flex items-center gap-2 mb-4">
            <div className="p-2 rounded-lg bg-cyan-500/20">
              <Calculator className="w-5 h-5 text-cyan-400" />
            </div>
            <h3 className="font-semibold text-white">Estimated Cost</h3>
            <span className="text-xs text-slate-600 dark:text-slate-400 ml-1">(preview — actual fees calculated on submission)</span>
          </div>

          <div className="space-y-3">
            <div className="flex justify-between text-sm">
              <span className="text-slate-600 dark:text-slate-400">Gross Value</span>
              <span className="text-white">
                {formatCurrency(costs.grossValue, { currency: currencyForMarket(formData.market) })}
                {formData.market === "US" && (
                  <span className="text-slate-600 dark:text-slate-400 ml-1">({formatCurrency(costs.grossValueGBP)})</span>
                )}
              </span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-slate-600 dark:text-slate-400">Commission</span>
              <span className="text-white">{formatCurrency(costs.commission)}</span>
            </div>
            {costs.stampDuty > 0 && (
              <div className="flex justify-between text-sm">
                <span className="text-slate-600 dark:text-slate-400">Stamp Duty (0.5%)</span>
                <span className="text-white">{formatCurrency(costs.stampDuty)}</span>
              </div>
            )}
            {costs.fxFee > 0 && (
              <div className="flex justify-between text-sm">
                <span className="text-slate-600 dark:text-slate-400">FX Fee (0.15%)</span>
                <span className="text-white">{formatCurrency(costs.fxFee)}</span>
              </div>
            )}
            <div className="pt-3 border-t border-slate-700">
              <div className="flex justify-between">
                <span className="font-medium text-white">Est. Total Cost</span>
                <span className="font-bold text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-violet-400">
                  {formatCurrency(costs.totalCost)}
                </span>
              </div>
            </div>
            {/* ST-07 (BLG-FE-197, v9.10): risk to the system stop only */}
            <div className="pt-3 border-t border-slate-700">
              <div className="flex justify-between text-sm">
                <span className="text-slate-600 dark:text-slate-400">Risk (to stop)</span>
                <span className="text-rose-400 font-medium" data-testid="risk-to-stop">
                  {costs.totalRisk != null ? formatCurrency(costs.totalRisk) : costs.stopAtOrBelowZero ? "—" : "Calculated on save"}
                </span>
              </div>
            </div>
          </div>
        </motion.div>
      )}

      {/* Pre-Entry Checks (ST-01, BLG-FE-244, v9.15) — position_form.md §Pre-Entry Checks */}
      {showPreEntryChecks ? (
        <PreEntryValidationPanel
          ticker={normalizedTicker}
          market={formData.market}
          quantity={formData.shares}
          entryPrice={formData.entry_price}
          stopPrice={costs.systemStop}
          overrideAcknowledged={preEntryAck}
          onOverrideChange={setPreEntryAck}
          onWarningsChange={setPreEntryNeedsAck}
          showWaiting
        />
      ) : (
        <p data-testid="pre-entry-checks-on-plan" className="text-xs text-slate-600 dark:text-slate-400">
          Pre-entry checks were run on the linked plan.
        </p>
      )}

      {/* Trade Plan Linkage Advisory (ST-28, EPIC-06, v9.4, BLG-FEAT-95) —
          non-blocking, condition-driven, no dismiss control per
          position_form.md §Trade Plan Linkage Advisory. Surfaces an
          existing fact (plan-linkage absence); does not compute a
          recommendation or force a default action — §13 compliant. */}
      {!linkedPlanId && (
        <div
          data-testid="trade-plan-linkage-advisory"
          className="flex items-start gap-3 rounded-lg border border-amber-200 dark:border-amber-800 bg-amber-50 dark:bg-amber-950/30 px-4 py-3"
        >
          <Info className="w-4 h-4 text-amber-500 shrink-0 mt-0.5" />
          <div className="flex-1 min-w-0 space-y-2">
            <p className="text-sm text-amber-800 dark:text-amber-200">
              No trade plan linked to this position. Consider creating one before entering — or continue without.
            </p>
            <Link
              to={`${createPageUrl("TradePlan")}${formData.ticker ? `?ticker=${encodeURIComponent(formData.ticker)}` : ""}`}
            >
              <Button
                variant="outline"
                size="sm"
                className="border-amber-300 dark:border-amber-700 text-amber-700 dark:text-amber-300 hover:bg-amber-100 dark:hover:bg-amber-900/40"
              >
                Create Trade Plan
              </Button>
            </Link>
          </div>
        </div>
      )}

      {/* Submit */}
      <div className="flex flex-col items-end gap-1">
      <div className="flex justify-end gap-3">
        <Link to={createPageUrl("Positions")}>
          <Button variant="ghost" className="text-slate-600 dark:text-slate-400 hover:text-white hover:bg-slate-800">
            Cancel
          </Button>
        </Link>
        <Button
          onClick={handleSubmit}
          disabled={!isFormValid || showAtrError || costs.stopInvalid || preEntryAckRequired || createMutation.isPending}
          aria-describedby={preEntryAckRequired ? "pre-entry-ack-required" : undefined}
          className="bg-gradient-to-r from-cyan-500 to-violet-500 hover:from-cyan-400 hover:to-violet-400 text-white border-0 shadow-lg shadow-violet-500/25 disabled:opacity-50"
        >
          {createMutation.isPending ? (
            <>
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              Creating...
            </>
          ) : (
            <>
              <CheckCircle2 className="w-4 h-4 mr-2" />
              Create Position
            </>
          )}
        </Button>
      </div>
      {preEntryAckRequired && (
        <p id="pre-entry-ack-required" data-testid="pre-entry-ack-required" className="text-xs text-amber-700 dark:text-amber-400">
          Tick the acknowledgement in Pre-Entry Checks to save.
        </p>
      )}
      </div>
    </div>
  );
}
